mapper.select:
SELECT m.message_id, m.receiver_id, m.sender_id, m.type, m.target_type,
       m.target_id, m.content, m.is_read, m.created_at, m.updated_at,
       u.username AS sender_name, u.avatar_url AS sender_avatar_url
FROM messages m
LEFT JOIN users u ON m.sender_id = u.user_id

    m.receiver_id = #{param.receiverId}
    AND m.type = #{param.type}

ORDER BY m.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM messages

    receiver_id = #{param.receiverId}
    AND type = #{param.type}

mapper.update:
UPDATE messages SET is_read = 1
WHERE receiver_id = #{receiverId} AND is_read = 0 AND message_id IN
#{id}
